#!/usr/bin/env python3
"""Render the original, deterministic LATENTPUNK campaign motif (no samples)."""
from array import array
from pathlib import Path
import hashlib
import json
import math
import subprocess
import sys
import wave

ROOT = Path(__file__).resolve().parents[2]
RATE = 32000
BAR = 3.2
CHORDS = [(38, 53, 57, 62), (34, 53, 58, 62), (31, 55, 58, 62), (33, 52, 57, 60),
          (38, 53, 57, 65), (34, 53, 58, 65), (31, 55, 58, 62), (33, 52, 57, 64)]
MELODY = [74, 69, 70, 72, 77, 74, 70, 69]


def note_frequency(note):
    return 440.0 * 2.0 ** ((note - 69) / 12.0)


def main():
    directory = ROOT / 'assets/audio/campaign'
    originals = directory / 'originals'
    originals.mkdir(parents=True, exist_ok=True)
    wav_path = originals / 'shift_change.wav'
    output_path = directory / 'shift_change.ogg'
    frames = round(RATE * BAR * len(CHORDS))
    samples = array('h')
    frequencies = [[note_frequency(note) for note in chord] for chord in CHORDS]
    melody_frequencies = [note_frequency(note) for note in MELODY]
    for frame in range(frames):
        t = frame / RATE
        bar = min(int(t / BAR), len(CHORDS) - 1)
        local = t - bar * BAR
        attack = min(local / 0.24, 1.0)
        release = min((BAR - local) / 0.48, 1.0)
        envelope = attack * release * (0.65 + 0.35 * math.exp(-local / 2.5))
        left = right = 0.0
        for voice, frequency in enumerate(frequencies[bar]):
            phase = math.tau * frequency * t
            amplitude = 0.040 if voice == 0 else 0.022
            tone = math.sin(phase) + 0.10 * math.sin(phase * 2) + 0.035 * math.sin(phase * 3)
            stereo = 0.82 if voice % 2 == 0 else 1.0
            left += tone * amplitude * envelope * stereo
            right += tone * amplitude * envelope * (1.82 - stereo)
        pluck_time = local - 0.8
        if pluck_time >= 0:
            pluck = min(pluck_time / 0.012, 1.0) * math.exp(-pluck_time / 0.65) * release
            phase = math.tau * melody_frequencies[bar] * pluck_time
            tone = math.sin(phase) + 0.12 * math.sin(phase * 2)
            left += tone * pluck * 0.024
            right += tone * pluck * 0.020
        samples.extend((round(max(-1.0, min(1.0, left)) * 32767), round(max(-1.0, min(1.0, right)) * 32767)))
    if sys.byteorder != 'little':
        samples.byteswap()
    with wave.open(str(wav_path), 'wb') as stream:
        stream.setnchannels(2)
        stream.setsampwidth(2)
        stream.setframerate(RATE)
        stream.writeframes(samples.tobytes())
    subprocess.run(['ffmpeg', '-y', '-v', 'error', '-i', str(wav_path), '-c:a', 'libvorbis', '-q:a', '5',
                    '-metadata', 'title=Shift Change', '-metadata', 'artist=LATENTPUNK project', str(output_path)], check=True)
    provenance = {
        'title': 'Shift Change', 'duration_seconds': BAR * len(CHORDS),
        'origin': 'Original deterministic composition for LATENTPUNK; generated by the included renderer without external audio samples.',
        'renderer': '.github/scripts/render_campaign_music.py',
        'original': str(wav_path.relative_to(ROOT)), 'runtime': str(output_path.relative_to(ROOT)),
        'sha256': {str(path.relative_to(ROOT)): hashlib.sha256(path.read_bytes()).hexdigest() for path in (wav_path, output_path)},
    }
    (directory / 'provenance.json').write_text(json.dumps(provenance, ensure_ascii=False, indent=2) + '\n')
    print(json.dumps(provenance, ensure_ascii=False, indent=2))


if __name__ == '__main__':
    main()
